import { Entity, PrimaryKey, Property, Unique } from '@mikro-orm/decorators/legacy';
import type { Permission } from '../../modules/permissions/permission.js';
import type { Role } from '../../modules/roles/role.js';

export const ROLES_NAME_UNIQUE = 'roles_name_unique';

@Entity({ tableName: 'roles' })
@Unique({ name: ROLES_NAME_UNIQUE, properties: ['name'] })
export class RoleEntity implements Role {
  /** A UUIDv7 generated by the repository, so ids sort by creation time. */
  @PrimaryKey({ type: 'uuid' })
  id!: string;

  @Property({ type: 'text' })
  name!: string;

  @Property({ type: 'text' })
  description!: string;

  @Property({ type: 'text[]' })
  permissions!: Permission[];

  @Property({ type: 'boolean', default: false })
  isSystem!: boolean;

  @Property({ type: 'datetime', defaultRaw: 'now()' })
  createdAt!: Date;

  /** Set to the current time by every update. */
  @Property({ type: 'datetime', defaultRaw: 'now()' })
  updatedAt!: Date;
}
